import heapq


def _dependency_solver(data, name_order, preference):
    packages = data['packages']
    names = sorted(packages, reverse=(name_order == 'descending'))
    roots = data['roots']
    features = set(data.get('features', []))
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    rows = {name: {row['version']: row for row in versions}
            for name, versions in packages.items()}
    domains = [[-1] + sorted(rows[name]) for name in sorted(packages)]
    all_names = sorted(packages)
    best_vector = None
    best_versions = None

    for values in product(*domains):
        assignment = dict(zip(all_names, values))
        if any(assignment.get(name, -1) == -1 or
               not bounds[0] <= assignment[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue
        valid = True
        edges = {}
        for name, version in assignment.items():
            if version == -1:
                continue
            if version in blocked.get(name, ()) or name in pins and version != pins[name]:
                valid = False
                break
            row = rows[name].get(version)
            if row is None:
                valid = False
                break
            edges[name] = []
            for dep in row.get('deps', []):
                feature = dep.get('feature', '')
                if feature and feature not in features:
                    continue
                target = dep['name']
                target_version = assignment[target]
                if target_version == -1 or not dep['min'] <= target_version <= dep['max']:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        # The installation must be precisely the dependency closure of its roots.
        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges.get(name, ()))
        if any((assignment[name] != -1) != (name in reachable) for name in all_names):
            continue

        # Reject every cycle, including self-loops.
        state = {}
        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            if any(not visit(child) for child in edges.get(name, ())):
                return False
            state[name] = 2
            return True

        if any(not visit(name) for name in reachable):
            continue

        vector = tuple(assignment[name] for name in names)
        if best_vector is None or (vector < best_vector if preference == 'minimum'
                                   else vector > best_vector):
            best_vector = vector
            best_versions = {name: assignment[name] for name in all_names
                             if assignment[name] != -1}

    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}


def _ledger(data):
    cutoff = data.get('cutoff', 10**9)
    winners = {}
    for position, event in enumerate(data['events']):
        sequence = event.get('sequence', 0)
        if sequence > cutoff:
            continue
        event_id = event.get('id', 'anonymous:' + str(position))
        key = (sequence, event.get('revision', 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get('opening', {}))
    half_up = data['rounding'] == 'half_up'

    def rounded(numerator):
        if half_up:
            return (numerator + 5000) // 10000
        return numerator // 10000

    for _, event in winners.values():
        if event.get('void', False):
            continue
        raw = event['price'] * event.get('quantity', 1)
        discount = min(10000, max(0, event.get('discount_bp', 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(net * event.get('tax_bp', 0))
        total = net + tax
        if event.get('kind') == 'refund':
            total = -total
        key = event.get('account', 'default') + '|' + event.get('currency', 'USD')
        balances[key] = balances.get(key, 0) + total
    return {'balances': balances}


def _quota_intervals(data):
    jobs = data['jobs']
    k = data['k']
    blocked = set(data.get('blocked', []))
    mandatory = set(data.get('mandatory', []))
    quotas = data.get('quotas', {})
    options = [job for job in jobs if job['id'] not in blocked]
    if not mandatory.issubset({job['id'] for job in options}):
        return {'error': 'impossible'}
    best_value = None
    best_ids = None
    for subset in combinations(options, k):
        ids = tuple(sorted(job['id'] for job in subset))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            group = job['group']
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job['start'], job['end']))
        if any(ordered[i]['end'] > ordered[i + 1]['start']
               for i in range(len(ordered) - 1)):
            continue
        value = sum(job['value'] for job in subset)
        if (best_value is None or value > best_value or
                value == best_value and ids < best_ids):
            best_value, best_ids = value, ids
    if best_value is None:
        return {'error': 'impossible'}
    return {'selected': list(best_ids), 'value': best_value}


def _temporal_routes(data):
    required = data.get('required', [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bit.get(data['source'], 0)
    coupons = data['coupons']
    start = data['start']
    # Distances preserve visited requirements and coupon usage as part of state.
    initial = (data['source'], initial_mask, 0)
    distances = {initial: start}
    queue = [(start, data['source'], initial_mask, 0)]
    graph = [[] for _ in range(data['n'])]
    for edge in data['edges']:
        graph[edge['u']].append(edge)

    while queue:
        arrival, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distances.get(state) != arrival:
            continue
        if node == data['target'] and mask == full and used == coupons:
            return {'arrival': arrival}
        for edge in graph[node]:
            depart = max(arrival, edge['open'])
            if depart >= edge['close']:
                continue
            durations = [edge['duration']]
            if used < coupons:
                durations.append(max(2, edge['duration'] - edge.get('discount', 0)))
            for option, duration in enumerate(durations):
                next_used = used + (1 if option else 0)
                next_time = depart + duration
                if next_time > data['deadline']:
                    continue
                next_node = edge['v']
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, next_used)
                if next_time < distances.get(next_state, float('inf')):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time, next_node, next_mask, next_used))
    return {'arrival': None}


